10: def review_inspections(request: Any) -> dict[str, Any]:
11:     """Validate, assess current coverage, propose stations, and explain work transfers."""
12:     names, edges, selected = prepare_request(request)
13:     current = describe_plan(names, edges, selected)
14:     proposed = describe_plan(names, edges, min_vertex_cover_bruteforce(edges, len(names)))
15:     return {"station_count": len(names), "connection_count": len(edges),
16:             "current": current, "proposed": proposed,
17:             "changes": compare_plans(names, edges, current, proposed)}
18: 
