21:     print(json.dumps(review_inspections(json.load(sys.stdin)), indent=2))

FILE inspection.py
1: """Validation, coverage assessment, worklists and changes for endpoint inspections."""
2: 
3: import itertools
4: from typing import Any
5: 
6: 
7: def prepare_request(request: Any) -> tuple[list[str], list[tuple[int, int]], set[int]]:
8:     """Read all fields; an incomplete current coverage is legal and must be reported."""
9:     if not isinstance(request, dict) or set(request) != {"stations", "connections", "current_stations"}:
10:         raise ValueError("Expected stations, connections and current_stations")
11:     names = request["stations"]
12:     if not isinstance(names, list) or len(names) > 16:
13:         raise ValueError("stations must be a list of at most 16 names")
14:     if any(not isinstance(name, str) or not name for name in names) or len(set(names)) != len(names):
15:         raise ValueError("Station names must be unique nonempty strings")
16:     index = {name: i for i, name in enumerate(names)}
17:     connections = request["connections"]
18:     if not isinstance(connections, list):
19:         raise ValueError("connections must be a list")
20:     edges = set()
21:     for pair in connections:
22:         if not isinstance(pair, list) or len(pair) != 2:
23:             raise ValueError("Connections require two endpoints")
24:         first, second = pair
25:         if not isinstance(first, str) or not isinstance(second, str):
26:             raise ValueError("Endpoints must be names")
27:         if first not in index or second not in index or first == second:
28:             raise ValueError("Endpoints must be distinct known stations")
29:         edges.add(tuple(sorted((index[first], index[second]))))
30:     current = request["current_stations"]
31:     if not isinstance(current, list):
32:         raise ValueError("current_stations must be a list")
33:     selected = set()
34:     for name in current:
35:         if not isinstance(name, str) or name not in index or index[name] in selected:
36:             raise ValueError("Current stations must be distinct known names")
37:         selected.add(index[name])
38:     return list(names), sorted(edges), selected
39: 
40: 
41: def describe_plan(names: list[str], edges: list[tuple[int, int]], selected: set[int]) -> dict[str, Any]:
42:     """Assign each covered connection once to its earliest selected endpoint."""
43:     assigned = {i: [] for i in sorted(selected)}
44:     uncovered = []
45:     for u, v in edges:
46:         pair = [names[u], names[v]]
47:         if u in selected:
48:             assigned[u].append(pair)
49:         elif v in selected:
50:             assigned[v].append(pair)
51:         else:
52:             uncovered.append(pair)
53:     return {"selected_stations": [names[i] for i in sorted(selected)],
54:             "selected_count": len(selected), "covered_connection_count": len(edges) - len(uncovered),
55:             "uncovered_connections": uncovered,
56:             "checklists": [{"station": names[i], "connections": pairs} for i, pairs in assigned.items()]}
57: 
58: 
59: def compare_plans(names: list[str], edges: list[tuple[int, int]], current: dict, proposed: dict) -> dict:
60:     """Describe station activation and connection responsibility changes independently."""
61:     old_set, new_set = set(current["selected_stations"]), set(proposed["selected_stations"])
62: 
63:     def owners(plan: dict) -> dict:
64:         return {tuple(pair): row["station"] for row in plan["checklists"] for pair in row["connections"]}
65: 
66:     old, new = owners(current), owners(proposed)
67:     pairs = [(names[u], names[v]) for u, v in edges]
68:     return {"add_stations": [name for name in names if name in new_set - old_set],
69:             "remove_stations": [name for name in names if name in old_set - new_set],
70:             "selected_count_delta": len(new_set) - len(old_set),
71:             "newly_covered_connections": [list(pair) for pair in pairs if pair not in old and pair in new],
72:             "reassigned_connections": [{"connection": list(pair), "from_station": old.get(pair),
73:                                         "to_station": new.get(pair)}
74:                                        for pair in pairs if old.get(pair) != new.get(pair)]}
75: 
76: 
77: def min_vertex_cover_bruteforce(edges, n):
78:     nodes = list(range(n))
79:     best_cover = None
80:     for r in range(n + 1):
81:         for subset in itertools.combinations(nodes, r):
82:             cover = set(subset)
83:             ok = True
84:             for u, v in edges:
85:                 if u not in cover and v not in cover:
86:                     ok = False
87:                     break
88:             if ok:
89:                 best_cover = cover
90:                 return best_cover
91:     return best_cover

