          "computational_intent",
          "admissible_migration_contracts",
          "classical_tests",
          "semantic_oracle",
          "resource_expectations",
          "annotation_rationale",
          "annotators",
          "review"
        ],
        "properties": {
          "structural_eligibility": {
            "type": "boolean"
          },
          "practical_suitability": {
            "type": "boolean"
          },
          "benchmark_supported": {
            "type": "boolean"
          },
          "expected_decision": {
            "enum": [
              "QUANTUMIZE",
              "REMAIN_CLASSICAL"
            ]
          },
          "computational_intent": {
            "type": "object"
          },
          "classical_tests": {
            "minItems": 1
          },
          "semantic_oracle": {
            "type": "object"
          },
          "resource_expectations": {
            "type": "object"
          },
          "annotation_rationale": {
            "type": "string",
            "minLength": 1
          },
          "annotators": {
            "minItems": 2
          }
        },
        "allOf": [
          {
            "if": {
              "properties": {
                "case_type": {
                  "const": "positive"
                }
              }
            },
            "then": {
              "properties": {
                "structural_eligibility": {
                  "const": true
                },
                "practical_suitability": {
                  "const": true
                },
                "benchmark_supported": {
                  "const": true
                },
                "admissible_migration_contracts": {
                  "minItems": 1
                }
              }
            }
          },
          {
            "if": {
              "properties": {
                "case_type": {
                  "enum": [
                    "negative",
                    "hard_negative"
                  ]
                }
              }
            },
            "then": {
              "required": [
                "negative_reason"
              ],
              "properties": {
                "negative_reason": {
                  "type": "string",
                  "minLength": 1
                }
              },
              "anyOf": [
                {
                  "properties": {
                    "structural_eligibility": {
                      "const": false
                    }
                  }
                },
                {
                  "properties": {
                    "practical_suitability": {
                      "const": false
                    }
                  }
                },
                {
                  "properties": {
                    "benchmark_supported": {
                      "const": false
                    }
                  }
                }
              ]
            }
          },
          {
            "if": {
              "properties": {
                "case_type": {
                  "const": "hard_negative"
                }
              }
            },
            "then": {
              "properties": {
                "candidate_regions": {
                  "minItems": 1
                }
              }
            }
          }
        ]
      }
    },
    {
      "if": {
        "properties": {
          "annotation_status": {
            "enum": [
              "ADJUDICATED",
              "FROZEN"
            ]
          }
        }
      },
      "then": {
        "properties": {
          "review": {
            "required": [
              "adjudicator_id",
              "resolution"
            ]
          }
        }
      }
    },
    {
      "if": {
        "properties": {
          "annotation_status": {
            "const": "FROZEN"
          }
        }
      },
      "then": {
        "required": [
          "benchmark_release"
        ]
      }
    }
  ]
}

